import {DAY,ads,cases,fresh,entries,remaining,isOpen,feedback,log,rerun,addRule,previewRule,smb,correctionValues} from './model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const qa=new URLSearchParams(location.search).get('qa')==='1';
const key=qa?'demo-daily-demo-qa-v1':'demo-daily-demo-v1';
let state,storageOK=true;try{state=JSON.parse(localStorage.getItem(key))||fresh();if(state.schema!==1)state=fresh();}catch{state=fresh();storageOK=false;}
let view='report',modal=null,draft=null,selected=[],decision='accepted',modalError='';
const statuses={pending:'待反馈',accepted:'已更新演示标准',exception:'仅本次允许',needs_fix:'待修正 / 待复查',closed:'复查通过',help:'需要协助',MATCH:'规则已补，页面相符',MISSING_RULE:'缺少规则',URL_MISMATCH:'已有规则，页面不符',RULE_CONFLICT:'规则冲突'};
const button=(label,action,extra='',kind='secondary')=>`<button class="${kind}" data-action="${action}" ${extra}>${label}</button>`;
const caseBy=id=>cases.find(c=>c.id===id);
const destinationLink=(url,label,stage)=>`<div class="destination-ref"><span class="destination-stage">${esc(stage)}</span><b>${esc(label)}</b><a class="destination-url" href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="打开${esc(label)}：${esc(url)}">${esc(url)}<span aria-hidden="true"> ↗</span></a></div>`;
const destinationDiff=c=>`<div class="destination-diff">${destinationLink(c.before_url,c.before,'调整前（演示）')}<span class="destination-arrow" aria-hidden="true">→</span>${destinationLink(c.after_url,c.after,'调整后（演示）')}</div><p class="destination-source">网址使用 example.com 占位；页面、广告与调整关系均为虚构示例。</p>`;

const entityHeading=c=>c.title;
const entityContext=c=>c.level==='adset'?`广告组（Ad Set）：${c.entity_name} · 所属 Campaign：${c.campaign_name}`:c.desc;
const affectedAds=(c,rows)=>`<details class="ad-details"><summary>影响 ${c.ids.length} 条广告 · 展开查看</summary><div class="ad-scroll">${rows.map(({ad,status})=>`<div class="ad-row"><span><b>广告（Ad）：${esc(ad.name)}</b><small>广告组（Ad Set）：${esc(ad.adset)}</small><small>所属 Campaign：${esc(ad.campaign)}</small></span><em>${statuses[status]}</em></div>`).join('')}</div></details>`;
const bucket=c=>c.id==='rule'&&state.rules.length&&entries(state,c).some(x=>x.status!=='MISSING_RULE'&&x.status!=='MATCH')?'issue':c.kind;
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{storageOK=false;}render();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const pendingCases=()=>cases.filter(c=>c.kind!=='history'&&remaining(state,c));
function card(c){const n=remaining(state,c),done=!n;const rows=entries(state,c),allClosed=rows.every(r=>r.status==='closed');const title=c.id==='rule'?(done?'新品广告的落地页规则已补齐':state.rules.length?'新品广告已有规则，仍需核对页面':c.title):allClosed?'复查通过：'+c.title:c.title;const description=c.id==='new'&&!remaining(state,caseBy('rule'))?'2 个 Ad Set；4 条新品广告的落地页规则已补齐，新增本身仍需确认。':c.desc;return `<article class="item ${c.kind==='issue'?'risk':''} ${done?'done':''}"><div class="item-top"><span class="tag">${c.tag}</span><span class="priority ${c.priority==='P0'?'p0':''}">${c.priority}</span><span class="status ${done?'green':''}">${done?'已处理':rows.every(r=>r.status==='needs_fix')?'等待修正与复查':`${c.level==='adset'?'1 个广告组':n+' 条'}待处理`}</span></div><h3>${esc(c.level==='adset'?entityHeading(c):title)}</h3><p class="sub">${esc(c.level==='adset'?entityContext(c):description)}</p>${c.level==='adset'?`<p class="level-issue">检查项：${esc(c.tag)} · ${allClosed?'复查已通过':'广告组设置与规则不符'}</p>`:''}${c.id==='page'?destinationDiff(c):`<div class="diff"><span>${esc(c.before)}</span><i>→</i><b>${esc(allClosed?'已修正，复查符合要求':c.id==='rule'&&done?'规则已确认，4 条页面相符':c.after)}</b></div>`}<div class="item-bottom"><span>${c.level==='adset'?`广告组设置 · 影响 ${c.ids.length} 条广告`:`${c.ids.length} 条广告 · 名称可展开查看`}</span>${button(done?'查看处理记录':c.id==='rule'?'补充规则':'查看并反馈','open',`data-id="${c.id}"`,done?'secondary':'primary')}</div></article>`;}
function group(kind,title,subtitle,icon){const list=cases.filter(c=>bucket(c)===kind);return `<section class="report-section" id="section-${kind}"><div class="section-title"><span class="section-icon">${icon}</span><div><h2>${title}</h2><p>${subtitle}</p></div><span class="section-count">${list.length} 组</span></div>${list.filter(c=>remaining(state,c)).map(card).join('')||'<div class="empty">这一块没有待处理事项。</div>'}${list.some(c=>!remaining(state,c))?`<details class="history"><summary>已处理 ${list.filter(c=>!remaining(state,c)).length} 组 · 展开查看记录</summary>${list.filter(c=>!remaining(state,c)).map(card).join('')}</details>`:''}</section>`;}
function render(){const todo=pendingCases().length,done=5-todo;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="./"><span>e</span><b>demo<small>广告检查工作台</small></b></a><div class="nav-label">项目协作</div><nav>${[['report','今日检查','◫'],['feishu','飞书卡片预览','▤'],['activity','规则与处理记录','↺']].map(([id,label,icon])=>`<button data-action="view" data-view="${id}" class="nav ${view===id?'active':''}"><span>${icon}</span>${label}${id==='report'?`<em>${todo}</em>`:''}</button>`).join('')}</nav><a class="back" href="../media-plan/">品牌 Media Plan 核对 →</a><a class="back" href="../">← 返回首次接入</a><div class="sidebar-bottom"><span class="dot"></span> 本地交互演示<p>不连接飞书 · 不修改广告<br>演示记录与真实标准版隔离</p>${button('重置演示','reset','','text')}</div></aside><div class="workspace"><header><span>demo-DE <small>/ 每日配置检查</small></span><span class="avatar">H</span><span>demo-reviewer <small>演示负责人</small></span></header><main><div class="demo-banner"><b>虚构案例演示</b> 广告名称、数量、变化和报错均为模拟；网址为 example.com 占位地址。${qa?' · 独立测试副本':''}${!storageOK?' · 浏览器存储不可用，请下载记录后保存。':''}</div><div class="heading"><div><div class="eyebrow">DAILY REVIEW · ${DAY}</div><h1>${view==='report'?'今天改了什么，需要确认什么':view==='feishu'?'在群里，也能把事情处理完':'每次确认，都有来处'}</h1><p>${view==='report'?'先看调整，再看问题。相同问题合并，只把需要你判断的留下来。':view==='feishu'?'卡片先说明问题，再给出操作。这里模拟飞书交互，不会向群里发送消息。':'规则何时补充、哪些调整被接受、哪些问题仍未解决，都留在这里。'}</p></div>${button('模拟再跑一次','rerun','','secondary')}</div>${view==='report'?reportView(todo,done):view==='feishu'?feishuView():activityView()}</main></div>`;}
function reportView(todo,done){return `${remaining(state,caseBy('market'))?`<button class="priority-highlight" data-action="open" data-id="market"><span class="priority p0">P0 · 虚构案例</span><strong>投放国家不符：应投德国，实际投法国</strong><span>广告组：Country_Test_FR · 所属 Campaign：DE_E1_ALWAYS_ON</span><b>查看并反馈 →</b></button>`:''}<div class="stats">${[['change','本次调整',3,'按组反馈，不用逐条翻表'],['issue','疑似问题',cases.filter(c=>bucket(c)==='issue'&&remaining(state,c)).length,'只展示有依据的规则不符'],['rule','待补规则',cases.filter(c=>bucket(c)==='rule'&&remaining(state,c)).length,'先给建议，再由负责人确认']].map(([id,label,n,sub])=>`<button class="stat" data-action="section" data-section="${id}"><span>${label}</span><strong>${n}<small>${id==='change'?'组':'项'}</small></strong><p>${sub}</p></button>`).join('')}</div><div class="report-grid"><div>${group('change','本次调整','把正常调整纳入标准，例外单独留下。','01')}${group('issue','疑似问题','确认有问题后，还需修正并复查。','02')}${group('rule','待补规则','数据已经拿到，只缺适用规则。','03')}<details class="history"><summary>此前未处理 · ${remaining(state,caseBy('old'))?1:0} 项 <small>相同问题不重复计入今日新增</small></summary>${card(caseBy('old'))}</details><details class="coverage"><summary>检查范围与数据缺口</summary><p>演示范围：48 条广告；其中 2 条的增强功能状态检查不到，其他已获取字段可继续核对。</p><p>“缺少规则”由负责人补充；“数据没拿到”由系统补取。两者不会混在一起，也不会写成已通过。</p><p>每次复查都使用这份演示数据，不访问 Meta 或飞书。检查到的问题按账户、所属层级的对象、检查项和原因去重。广告组问题只确认一次。</p></details></div><aside class="todo"><div class="eyebrow">YOUR REVIEW</div><h2>${todo?`今天还差 ${todo} 件`:'今日反馈已完成'}</h2><p>${done} / 5 件已处理${state.feedback.market?.[caseBy('market').ids[0]]?.status==='needs_fix'?'；地区问题仍等复查':''}</p><div class="progress"><span style="width:${done*20}%"></span></div>${pendingCases().map(c=>`<button class="todo-link" data-action="open" data-id="${c.id}"><span class="mini-dot ${c.kind==='issue'?'red':''}"></span><span>${esc(c.tag)}<small>${c.level==='adset'?'1 个广告组':remaining(state,c)+' 条'}待处理</small></span><b>↗</b></button>`).join('')||'<div class="empty">已记录你的反馈。此前未处理的问题和数据缺口仍保留。</div>'}<div class="todo-note">“看过了”不等于“已确认”。<br>确认正常、指出问题或请求协助，都会留下明确状态。</div><div class="run-info">演示检查第 ${state.run} 次<br>规则版本 v${state.ruleVersion} · 记录保存在本浏览器</div>${button('下载演示处理记录','download','','text')}</aside></div>`;}
function feishuView(){const c=caseBy('rule'),n=remaining(state,c);return `<div class="chat-layout"><section class="chat-window"><div class="chat-header"><div class="group-avatar">e</div><div><b>demo · 广告检查测试群</b><small>飞书群卡片交互示意</small></div><span>···</span></div><div class="chat-time">11 月 5 日 09:30 · 演示</div><div class="message"><div class="bot-avatar">检</div><div class="bubble-wrap"><span class="sender">广告小子 <small>机器人 · 演示</small></span><div class="feishu-card"><div class="feishu-card-title">今日广告检查 · demo-DE</div><div class="card-body"><h3>${remaining(state,caseBy('market'))?'国家不符：应投德国，实际投法国':'今日调整与确认进度'}</h3><p>${pendingCases().length} 件仍待处理 · 虚构案例</p><p>3 组调整 · ${cases.filter(c=>bucket(c)==='issue'&&remaining(state,c)).length} 项疑似问题 · ${cases.filter(c=>bucket(c)==='rule'&&remaining(state,c)).length} 组待补规则</p><hr><b>落地页已变更：8 条广告从 E1 产品页改为黑五活动页</b>${destinationDiff(caseBy('page'))}<p>8 条广告，共同变化已合并。</p><div class="actions">${button('正常，更新标准','open','data-id="page"','primary')}${button('需要修正','open','data-id="page" data-decision="needs_fix"')}</div>${button('查看完整日报 →','view','data-view="report"','text')}</div></div></div></div>${remaining(state,caseBy('market'))?`<div class="message"><div class="bot-avatar">检</div><div class="bubble-wrap"><span class="sender">广告小子 · 虚构案例</span><div class="feishu-card issue-card"><div class="feishu-card-title">投放国家不符：应投德国，实际投法国</div><div class="card-body"><h3>广告组：Country_Test_FR</h3><p>所属 Campaign：DE_E1_ALWAYS_ON</p><div class="diff"><span>允许：德国（DE）</span><i>→</i><b>实际：法国（FR）</b></div><p>影响 1 条广告。请确认是否为允许的测试；如需修正，复查通过后才关闭。</p>${button('查看国家问题并反馈','open','data-id="market"','primary')}</div></div></div></div>`:''}<div class="message"><div class="bot-avatar">检</div><div class="bubble-wrap"><span class="sender">广告小子</span><div class="feishu-card amber-card"><div class="feishu-card-title">${n?(state.rules.length?'规则已补，仍需核对':'4 条新品广告缺少落地页规则'):'规则已确认'}</div><div class="card-body"><h3>DE_E1_LAUNCH · 4 条广告</h3><p>${n?(state.rules.length?'规则已保存，但仍有广告未匹配或页面不符，请继续处理。':'现在都去“小企业页面”，但还没有明确应该去哪里。'):'4 条广告已匹配确认的规则，当前页面核对通过。'}</p><div class="suggestion"><b>${state.rules.length?'最近确认的规则':'建议对应关系'}</b><p>${state.rules.length?`${esc(state.rules.at(-1).field)} 名称包含 <code>${esc(state.rules.at(-1).pattern)}</code><br>→ ${esc(state.rules.at(-1).url)}<br>${state.rules.at(-1).until?`有效至 ${state.rules.at(-1).until}`:'长期有效'}`:'Campaign 名称包含 <code>DE_E1_LAUNCH</code><br>→ 允许使用小企业页面'}</p></div><div class="actions">${button(n?'补充落地页规则':'查看规则','open','data-id="rule"','primary')}${n?button('我用一句话补充','rule-note'):''}</div><p class="small">在弹框中确认条件 → 预览广告 → 保存并重新核对。本页预览随保存更新；已发出的飞书消息暂不自动回写。</p></div></div></div></div></section><section class="chat-explain"><div class="eyebrow">TRY IT</div><h2>点开弹框，补一条规则</h2><ol><li><b>点「补充落地页规则」</b><p>例如：只允许这批广告，到月底。</p></li><li><b>看系统整理的确认草案</b><p>适用广告、目标页面和有效期，一起确认。</p></li><li><b>保存后重新核对</b><p>确认规则后重新匹配；仍不相符的继续作为问题。</p></li></ol><div class="notice">这版演示识别少量示例表达。正式的飞书消息接收、AI 理解与卡片回写尚未接通。</div></section></div>`;}
function activityView(){return `<div class="activity-grid"><section class="panel"><h2>已确认规则 <span class="tag">v${state.ruleVersion}</span></h2><p class="sub">v1 为演示起始规则；新规则单独记录，确认调整只更新对应对象的演示标准。</p>${state.rules.map(r=>`<article class="saved-rule"><b>v${r.version} · 落地页规则</b><p>${{campaign:'Campaign',adset:'Ad Set',name:'Ad'}[r.field]} 名称包含 <code>${esc(r.pattern)}</code></p><p class="url">${esc(r.url)}</p><small>${r.scope==='batch'?'仅限本次 4 条广告':'适用于以后符合条件的新广告'} · ${r.until?`有效至 ${r.until}`:'长期有效'}</small>${r.note?`<p>说明：${esc(r.note)}</p>`:''}${button('修改规则','edit-saved-rule',`data-version="${r.version}"`,'text')}</article>`).join('')||'<div class="empty">还没有新补充的规则。去「待补规则」确认一份建议即可。</div>'}</section><section class="panel"><h2>处理记录</h2>${state.events.length?state.events.map(e=>`<div class="event"><span class="mini-dot"></span><div><p>${esc(e.text)}</p><small>${new Date(e.at).toLocaleString('zh-CN')}</small></div></div>`).join(''):'<div class="empty">你的确认、补规则和复查操作会出现在这里。</div>'}${button('下载演示记录','download','','secondary')}</section></div>`;}
function showModal(type,id){modal={type,id};modalError='';if(type==='case'){selected=entries(state,caseBy(id)).filter(x=>isOpen(x.status)).map(x=>x.ad.id);decision=caseBy(id).kind==='change'?'accepted':'needs_fix';}if(type==='rule'){draft={field:'campaign',pattern:'DE_E1_LAUNCH',url:smb,scope:'batch',ids:caseBy('rule').ids,until:'',note:''};if(state.rules.length)draft={...state.rules.at(-1),replaceVersion:state.rules.at(-1).version};}drawModal();}
function closeModal(){modal=null;$('#overlay').innerHTML='';document.body.classList.remove('locked');}
function modalShell(title,content){$('#overlay').innerHTML=`<div class="scrim"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialog-head"><div><span class="eyebrow">虚构案例 · 非真实账户告警</span><h2>${esc(title)}</h2></div><button data-action="close" class="close" aria-label="关闭">×</button></div>${content}</section></div>`;document.body.classList.add('locked');$('#overlay .close').focus();}
function drawModal(){if(!modal)return;const c=caseBy(modal.id);if(modal.type==='case'){
 const rows=entries(state,c),open=rows.filter(x=>isOpen(x.status)),options=c.kind==='change'?[['accepted','正常，更新标准'],['exception','仅本次允许'],['needs_fix','需要修正']]:[['needs_fix','确实有问题'],['exception','这是允许的例外'],['help','需要协助判断']];
 modalShell(entityHeading(c),`<p class="sub">${esc(entityContext(c))}</p>${c.level==='adset'?`<p class="level-issue">检查项：${esc(c.tag)} · 问题出在广告组设置</p>`:''}${c.id==='page'?destinationDiff(c):`<div class="diff"><span>${esc(c.before)}</span><i>→</i><b>${esc(c.after)}</b></div>`}${c.level==='adset'?affectedAds(c,rows):`<details class="ad-details" open><summary>对应广告 · ${c.ids.length} 条（可取消本次不确认的条目）</summary><div class="ad-scroll">${rows.map(({ad,status})=>`<label class="ad-row"><input type="checkbox" data-select-ad="${ad.id}" ${selected.includes(ad.id)?'checked':''} ${!isOpen(status)?'disabled':''}><span><b>广告（Ad）：${esc(ad.name)}</b><small>所属 Ad Set：${esc(ad.adset)}</small><small>所属 Campaign：${esc(ad.campaign)}</small></span><em>${statuses[status]}</em></label>`).join('')}</div></details>`}${open.length?`<h3>${c.level==='adset'?'这个广告组怎么处理？':'这次怎么处理？'}</h3>${c.level==='adset'?'<p class="small">对此广告组确认一次即可，下属广告仅作影响明细。</p>':''}<div class="decision-grid">${options.map(([v,l])=>`<label><input type="radio" name="decision" value="${v}" ${decision===v?'checked':''}>${l}</label>`).join('')}</div><label class="field">补充说明 <small>仅本次允许时必填</small><textarea id="feedback-note" placeholder="例如：本次是计划内测试，仅允许这批广告。"></textarea></label><p class="notice">${c.level==='adset'?'本次反馈针对整个广告组。确认有问题后保留待修正，复查通过才关闭；例外也只对本次广告组设置生效。':'正常调整：更新所选广告的演示标准。仅本次允许：只记录这次例外。需要修正：保留为待处理，复查通过才关闭。'}</p><div id="dialog-error" class="error" role="alert">${esc(modalError)}</div><div class="dialog-actions">${rows.some(x=>x.status==='needs_fix')?button('演示修正后的复查','recheck-modal'):''}${button(c.level==='adset'?'确认这个广告组的反馈':'确认所选广告的反馈','submit-feedback','','primary')}</div>`:'<div class="notice success">这组已处理，记录已保存。</div>'}`);
 }else if(modal.type==='rule'){
 modalShell('给新品广告补充落地页规则',`<div class="rule-steps"><b>1 确认规则</b><span>→</span><span>2 预览范围</span><span>→</span><span>3 保存并核对</span></div><div class="suggestion"><b>这次需要补充：4 条新品广告的落地页规则</b><p>广告组（Ad Set）：SMB_New<br>所属 Campaign：DE_E1_LAUNCH</p><p>当前实际页面（演示）：<a class="destination-url" href="${esc(smb)}" target="_blank" rel="noopener noreferrer">${esc(smb)}</a></p><p class="small">下面是预填建议，保存前请确认它是否符合投放计划。国家和主页规则独立确认。</p></div><label class="field">你也可以用一句话补充<textarea id="rule-note" placeholder="试试：只允许这批广告，到月底。">${esc(draft.note)}</textarea></label>${button('整理这句话为草案','parse-note','','text')}<p class="small">演示支持“这批 / 以后”“月底”“活动页”等表达；其他说明保留为备注，条件仍需你核对。</p><div class="form-grid"><label class="field">筛选层级<select id="rule-field">${[['campaign','Campaign 名称'],['adset','Ad Set 名称'],['name','Ad 名称']].map(([v,l])=>`<option value="${v}" ${draft.field===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">名称包含<input id="rule-pattern" value="${esc(draft.pattern)}"></label></div><label class="field">允许的完整落地页<input id="rule-url" value="${esc(draft.url)}"></label><div class="form-grid"><label class="field">生效范围<select id="rule-scope"><option value="batch" ${draft.scope==='batch'?'selected':''}>仅本次这 4 条广告</option><option value="future" ${draft.scope==='future'?'selected':''}>以后符合条件的新广告也适用</option></select></label><label class="field">有效至 <small>不填则长期有效</small><input id="rule-until" type="date" min="${DAY}" value="${esc(draft.until)}"></label></div><div class="dialog-actions">${button('先看匹配结果 →','preview-rule','','primary')}</div>`);
 }else if(modal.type==='rule-preview'){
 const p=previewRule(draft,state);modalShell('确认这条规则会影响哪些广告',`<div class="rule-steps"><span>1 确认规则</span><span>→</span><b>2 预览范围</b><span>→</span><span>3 保存并核对</span></div><div class="rule-summary"><b>${{campaign:'Campaign',adset:'Ad Set',name:'Ad'}[draft.field]} 名称包含 ${esc(draft.pattern)}</b><p class="url">→ ${esc(draft.url)}</p><p>${draft.scope==='batch'?'仅本次 4 条广告':'包括以后符合条件的新广告'} · ${draft.until?`有效至 ${draft.until}`:'长期有效'}</p></div><div class="preview-metrics"><div><b>${p.targets.length}</b>匹配广告</div><div><b>${p.different.length}</b>当前页面不符</div><div><b>${p.conflicts.length}</b>规则冲突</div></div>${p.errors.map(x=>`<p class="error">${esc(x)}</p>`).join('')}${p.extra.length?`<p class="notice">这个条件还覆盖了本次待补规则之外的 ${p.extra.length} 条广告，请展开核对。</p>`:''}<details class="ad-details" open><summary>匹配的广告名称</summary><div class="ad-scroll">${p.targets.map(a=>`<div class="ad-row"><span><b>${esc(a.name)}</b><small>广告组（Ad Set）：${esc(a.adset)}</small><small>所属 Campaign：${esc(a.campaign)}</small><small>${esc(a.url)}</small></span></div>`).join('')||'<p>没有匹配广告。</p>'}</div></details><p class="small">确认只保存检查规则；不会改落地页。若当前页面不符合新规则，会继续列为问题。</p><div class="dialog-actions">${button('返回修改','edit-rule')}${button('确认规则，并重新核对','save-rule',p.errors.length?'disabled':'','primary')}</div>`);
 }else if(modal.type==='recheck')modalShell('演示：后台修正后重新核对',`<p>模拟负责人已经修改广告后台，再由系统读取并核对。本次只作用于演示数据。</p><label class="field">本次模拟读取到的配置<select id="mock-value"><option value="unchanged">仍未修正：${esc(correctionValues[c.id][0])}</option><option value="corrected">已修正：${esc(correctionValues[c.id][1])}</option></select></label><div class="dialog-actions">${button('执行演示复查','run-recheck','','primary')}</div>`);
 else if(modal.type==='reset')modalShell('重新体验这一版演示',`<p>只清除本浏览器的日报演示反馈和演示规则。首次接入中的真实填写和标准版不受影响。</p><div class="dialog-actions">${button('取消','close')}${button('重置演示记录','confirm-reset','','primary')}</div>`);
}
function readDraft(){draft={...draft,field:$('#rule-field').value,pattern:$('#rule-pattern').value.trim(),url:$('#rule-url').value.trim(),scope:$('#rule-scope').value,until:$('#rule-until').value,note:$('#rule-note').value.trim()};}
document.addEventListener('change',e=>{if(e.target.dataset.selectAd){selected=e.target.checked?[...new Set([...selected,e.target.dataset.selectAd])]:selected.filter(x=>x!==e.target.dataset.selectAd);}if(e.target.name==='decision')decision=e.target.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modal){const nodes=[...$('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,summary')];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='view'){view=b.dataset.view;render();window.scrollTo(0,0);}
 if(a==='section')$(`#section-${b.dataset.section}`)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(a==='open'){if(b.dataset.id==='rule'&&!remaining(state,caseBy('rule'))){view='activity';render();window.scrollTo(0,0);return;}showModal(b.dataset.id==='rule'?'rule':'case',b.dataset.id);if(b.dataset.decision){decision=b.dataset.decision;drawModal();}}
 if(a==='close')closeModal();
 if(a==='submit-feedback'){try{feedback(state,caseBy(modal.id),selected,decision,$('#feedback-note').value);persist();closeModal();toast(decision==='needs_fix'?'已记录，修正后还需要复查。':'反馈已保存到演示记录。');}catch(err){$('#dialog-error').textContent=err.message;}}
 if(a==='edit-saved-rule'){showModal('rule','rule');const r=state.rules.find(r=>r.version===+b.dataset.version);draft={...r,replaceVersion:r.version};drawModal();}
 if(a==='rule-note'){showModal('rule','rule');$('#rule-note').focus();}
 if(a==='parse-note'){readDraft();const t=draft.note;let changed=[];if(/这批|这4条|这 4 条|本次/.test(t)){draft.scope='batch';changed.push('仅本次 4 条');}if(/以后|未来/.test(t)){draft.scope='future';changed.push('未来匹配广告');}if(/月底/.test(t)){draft.until='2026-11-30';changed.push('有效至 11 月 30 日');}if(/活动页/.test(t)){draft.url='https://example.com/eu-de/black-friday-sale';changed.push('黑五活动页');}drawModal();toast(changed.length?`草案已整理：${changed.join('，')}。请核对。`:'这句话已保留为备注，请直接填写下面的条件。');}
 if(a==='preview-rule'){readDraft();modal.type='rule-preview';drawModal();}
 if(a==='edit-rule'){modal.type='rule';drawModal();}
 if(a==='save-rule'){try{const p=addRule(state,draft);persist();closeModal();toast(p.different.length?`规则已保存，仍有 ${p.different.length} 条页面不符。`:`规则已保存，${p.targets.length} 条匹配广告的页面核对通过。`);}catch(err){toast(err.message);}}
 if(a==='recheck-modal'){modal.type='recheck';drawModal();}
 if(a==='run-recheck'){state.corrections||={};state.corrections[modal.id]=correctionValues[modal.id][$('#mock-value').value==='corrected'?1:0];const count=rerun(state);persist();closeModal();toast(count?'复查已符合要求，原问题已关闭。':'复查仍不符合要求，问题继续保留。');}
 if(a==='rerun'){const count=rerun(state);persist();toast(`演示检查完成；没有新增重复问题。${count?'已关闭修正通过的地区问题。':''}`);}
 if(a==='reset')showModal('reset');
 if(a==='confirm-reset'){state=fresh();view='report';persist();closeModal();toast('演示已重置。');}
 if(a==='download'){const url=URL.createObjectURL(new Blob([JSON.stringify({demo:true,account:'demo-DE',report_date:DAY,...state},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='demo-DE-日报交互演示记录.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
render();

// Feishu uses explicit local deep links. Opening never submits feedback or saves rules.
const entry=new URLSearchParams(location.search);
if(entry.get('view')==='feishu'){view='feishu';render();}
const openCase=entry.get('open');
if(['rule','page','market','new','copy'].includes(openCase)){
 showModal(openCase==='rule'?'rule':'case',openCase);
}
